    // Força o escopo de seleção do bloco para "Entire Assembly", permitindo
    // selecionar faces de componentes quando o setup CAM é um assembly.
    // Equivale ao Selection.SelectionScope.AnyInAssembly do SelectionManager.
    // Usa GetEnumMembers para não depender do texto exato da versão do NX.
    // Se a propriedade não existir nesta versão, ajuste "Scope" diretamente
    // no CAVITY_MILL.dlx (Block UI Styler > face_select0 > Scope).



    private void EnableAssemblyScope(NXOpen.BlockStyler.UIBlock block)
    {
        if (block == null) return;
        PropertyList props = block.GetProperties();

        string[] candidates = { "Scope", "SelectionScope", "SelScope", "Selection Scope" };
        foreach (string name in candidates)
        {
            try
            {
                string[] members = props.GetEnumMembers(name);
                for (int i = 0; i < members.Length; i++)
                {
                    if (members[i].IndexOf("Assembly", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        props.SetEnum(name, i);
                        return;
                    }
                }
            }
            catch { /* tenta o próximo nome */ }
        }

        // Nada funcionou: mostra as propriedades disponíveis (sempre, sem DEBUG_MODE)
        string[] all = props.GetPropertyNames();
        theUI.NXMessageBox.Show("Scope não encontrado", NXMessageBox.DialogType.Information,
            "Propriedades do bloco face_select0:\n" + string.Join("\n", all));
    }
