    private const string LISTBOX_SELECTION_PROPERTY = "SelectedItems";

    // Prefixos de nome usados na sua biblioteca para ferramentas de desbaste
    // (Cavity Mill). Ajuste/adicione aqui se criar novas famílias de ferramenta.
    // Ex: "ENDMILL_D18MM", "CUTTER_D25_R.8".
    private static readonly string[] ROUGHING_TOOL_PREFIXES = { "CUTTER_", "ENDMILL_" };

    // Verifica se o nome da ferramenta bate com algum dos prefixos de desbaste.
    private static bool IsRoughingTool(string toolName)
    {
        foreach (string prefix in ROUGHING_TOOL_PREFIXES)
        {
            if (toolName.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }

    // Lê as ferramentas do CAMGroupCollection e popula o list_box0, mostrando
    // somente as ferramentas de desbaste (CUTTER_ e ENDMILL_), já que são as
    // que você normalmente usa no Cavity Mill. Precisa rodar no initialize_cb()
    // - se rodar só no ok_cb(), o diálogo já fecha antes de você ver a lista populada.
    private void PopulateToolListBox()
    {
        NXOpen.Part workPart = theSession.Parts.Work;
        if (workPart == null || list_box0 == null)
            return;

        List<string> toolNames = new List<string>();
        foreach (NXOpen.CAM.Tool tool in GetAllTools(workPart))
        {
            if (IsRoughingTool(tool.Name))
                toolNames.Add(tool.Name);
        }

        toolNames.Sort();
        list_box0.GetProperties().SetStrings("ListItems", toolNames.ToArray());

        if (toolNames.Count == 0)
            ShowError("Nenhuma ferramenta CUTTER_ ou ENDMILL_ encontrada na biblioteca desta peça.");
    }

    // Percorre o CAMGroupCollection e retorna todos os objetos do tipo Tool.
    private static IEnumerable<NXOpen.CAM.Tool> GetAllTools(NXOpen.Part workPart)
    {
        foreach (NXOpen.CAM.CAMObject obj in workPart.CAMSetup.CAMGroupCollection.ToArray())
        {
            NXOpen.CAM.Tool tool = obj as NXOpen.CAM.Tool;
            if (tool != null)
                yield return tool;
        }
    }

    // Busca um NCGroup pelo nome, mas só entre os objetos que realmente são do
    // tipo T pedido (Method, NCGroup de Program, FeatureGeometry, etc). Evita o
    // erro "Unable to cast object of type NCGroup to type X", que acontece
    // quando FindObject acha um grupo de OUTRA categoria com o mesmo nome
    // (ex: "NONE" existindo tanto em Method quanto em outra view).
    private static T FindGroupByNameAndType<T>(NXOpen.Part workPart, string groupName) where T : class
    {
        foreach (NXOpen.CAM.CAMObject obj in workPart.CAMSetup.CAMGroupCollection.ToArray())
        {
            NXOpen.CAM.NCGroup group = obj as NXOpen.CAM.NCGroup;
            if (group == null || !string.Equals(group.Name, groupName, StringComparison.OrdinalIgnoreCase))
                continue;

            T match = obj as T;
            if (match != null)
                return match;
        }
        return null;
    }

    // Busca ferramenta pelo nome sem usar FindObject (que lança exceção se não achar).
    private static NXOpen.CAM.Tool FindToolByName(NXOpen.Part workPart, string toolName)
    {
        foreach (NXOpen.CAM.Tool tool in GetAllTools(workPart))
        {
            if (string.Equals(tool.Name, toolName, StringComparison.OrdinalIgnoreCase))
                return tool;
        }
        return null;
    }

    // Lê o(s) item(ns) selecionado(s) do list_box0. Tenta primeiro a propriedade
    // já validada para esta versão do NX; se não vier nada (versão diferente,
    // nome mudou), cai no fallback por índices selecionados.
    private string[] GetListBoxSelectedItems(NXOpen.BlockStyler.ListBox listBox)
    {
        PropertyList props = listBox.GetProperties();

        try
        {
            string[] result = props.GetStrings(LISTBOX_SELECTION_PROPERTY);
            if (result != null && result.Length > 0)
                return result;
        }
        catch { /* propriedade não existe nesta versão - segue pro fallback */ }

        // Fallback: lê como índices selecionados e converte para os textos da lista.
        try
        {
            int[] selectedIndices = props.GetIntegerVector("SelectedItems");
            string[] allItems = props.GetStrings("ListItems");

            if (selectedIndices != null && allItems != null && selectedIndices.Length > 0)
            {
                string[] result = new string[selectedIndices.Length];
                for (int i = 0; i < selectedIndices.Length; i++)
                    result[i] = allItems[selectedIndices[i]];
                return result;
            }
        }
        catch { /* segue pro retorno vazio abaixo */ }

        return new string[0];
    }

