    // Monta um nome de operação único a partir do nome da ferramenta usada,
    // evitando colisão quando houver várias operações em sequência.
    private static string BuildOperationName(string toolName)
    {
        return OPERATION_SUBTYPE + "_" + toolName;
    }

    // Resolve a ferramenta selecionada no list_box0. Retorna null (e mostra o
    // erro correspondente) se nada estiver selecionado ou a ferramenta não existir.
    private NXOpen.CAM.Tool GetSelectedTool(NXOpen.Part workPart)
    {
        string[] selected = GetListBoxSelectedItems(list_box0);

        if (selected.Length == 0)
        {
            ShowError("Selecione uma ferramenta na lista antes de continuar.");
            return null;
        }

        NXOpen.CAM.Tool tool = FindToolByName(workPart, selected[0]);

        if (tool == null)
            ShowError("Ferramenta '" + selected[0] + "' não encontrada na biblioteca.");

        return tool;
    }

    // Resolve as faces selecionadas no face_select0. Retorna array vazio (e
    // mostra o erro correspondente) se nada estiver selecionado.
    //
    // NOTA (fix assembly): em projetos CAM criados sobre a peça importada
    // como componente de um assembly, as faces aqui retornadas normalmente
    // têm face.OwningPart != theSession.Parts.Work. Isso é esperado e é
    // tratado em ApplyCutAreaGeometry — não filtre nem descarte essas faces
    // aqui.
    private NXOpen.Face[] GetSelectedFaces()
    {
        NXOpen.TaggedObject[] selected = face_select0.GetSelectedObjects();

        if (selected == null || selected.Length == 0)
        {
            ShowError(
                "Selecione ao menos uma face antes de continuar.\n\n" +
                "Se você está num projeto CAM criado sobre a peça importada " +
                "(peça como componente de assembly), confirme que o Face " +
                "Collector do diálogo permite seleção em componentes " +
                "(escopo 'Entire Assembly'), e não apenas na Work Part.");
            return new NXOpen.Face[0];
        }

        NXOpen.Face[] faces = new NXOpen.Face[selected.Length];
        for (int i = 0; i < selected.Length; i++)
            faces[i] = (NXOpen.Face)selected[i];

        if (DEBUG_MODE)
            LogPartsDebug(faces);

        return faces;
    }

    // Aplica as faces selecionadas como Cut Area Geometry da operação.
    //
    // FIX: antes, a regra era SEMPRE criada com workPart.ScRuleFactory,
    // assumindo que toda face pertence à Work Part. Isso falha quando o
    // projeto CAM foi montado como assembly e a peça original virou
    // componente — nesse caso face.OwningPart aponta pra part do
    // componente, não pra workPart (o assembly).
    //
    // Agora agrupamos as faces por OwningPart e criamos uma FaceDumbRule
    // por dono, usando ownerPart.ScRuleFactory (não workPart.ScRuleFactory)
    // em cada grupo. Isso funciona tanto no cenário "peça sozinha" (onde
    // haverá só um grupo, igual a workPart) quanto no cenário "assembly"
    // (onde haverá um grupo por component part envolvida na seleção).
    private void ApplyCutAreaGeometry(NXOpen.Part workPart, NXOpen.CAM.CavityMillingBuilder builder, NXOpen.Face[] faces)
    {
        builder.CutAreaGeometry.InitializeData(false);

        NXOpen.CAM.GeometrySet geomSet = (NXOpen.CAM.GeometrySet)builder.CutAreaGeometry.GeometryList.FindItem(0);

        // Agrupa as faces pela part que realmente as possui.
        Dictionary<NXOpen.Part, List<NXOpen.Face>> facesByOwner = new Dictionary<NXOpen.Part, List<NXOpen.Face>>();
        foreach (NXOpen.Face f in faces)
        {
            NXOpen.Part owner = f.OwningPart as NXOpen.Part;
            if (owner == null)
                owner = workPart; // fallback de segurança, não deveria acontecer

            if (!facesByOwner.ContainsKey(owner))
                facesByOwner[owner] = new List<NXOpen.Face>();

            facesByOwner[owner].Add(f);
        }

        List<NXOpen.SelectionIntentRule> rules = new List<NXOpen.SelectionIntentRule>();

        foreach (KeyValuePair<NXOpen.Part, List<NXOpen.Face>> kvp in facesByOwner)
        {
            NXOpen.Part ownerPart = kvp.Key;
            NXOpen.Face[] ownerFaces = kvp.Value.ToArray();

            NXOpen.SelectionIntentRuleOptions ruleOptions = ownerPart.ScRuleFactory.CreateRuleOptions();
            ruleOptions.SetSelectedFromInactive(true);

            NXOpen.FaceDumbRule faceRule = ownerPart.ScRuleFactory.CreateRuleFaceDumb(ownerFaces, ruleOptions);
            ruleOptions.Dispose();

            rules.Add(faceRule);
        }

        if (rules.Count == 0)
        {
            ShowError("Não foi possível montar a(s) regra(s) de seleção de face (nenhuma face válida encontrada).");
            return;
        }

        geomSet.ScCollector.ReplaceRules(rules.ToArray(), false);
    }

    // Helper de diagnóstico: mostra Work Part, Display Part, e (se fornecido
    // um array de faces) a part dona de cada face selecionada. Ative via
    // DEBUG_MODE para confirmar rapidamente se o cenário é o de assembly.
    private void LogPartsDebug(NXOpen.Face[] faces)
    {
        NXOpen.Part workPart = theSession.Parts.Work;
        NXOpen.Part dispPart = theSession.Parts.Display;

        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        sb.AppendLine("Work Part:    " + (workPart != null ? workPart.Name : "(null)"));
        sb.AppendLine("Display Part: " + (dispPart != null ? dispPart.Name : "(null)"));

        if (workPart != null && dispPart != null && !string.Equals(workPart.Name, dispPart.Name, StringComparison.OrdinalIgnoreCase))
            sb.AppendLine("=> Work Part e Display Part SÃO DIFERENTES (cenário de assembly provável).");

        if (faces != null && faces.Length > 0)
        {
            sb.AppendLine();
            sb.AppendLine("Faces selecionadas (" + faces.Length + "):");
            for (int i = 0; i < faces.Length; i++)
            {
                NXOpen.Part owner = faces[i].OwningPart as NXOpen.Part;
                string ownerName = owner != null ? owner.Name : "(desconhecida)";
                bool diff = workPart != null && owner != null && !string.Equals(owner.Name, workPart.Name, StringComparison.OrdinalIgnoreCase);
                sb.AppendLine("  Face " + i + " -> OwningPart: " + ownerName + (diff ? "  [DIFERENTE DA WORK PART]" : ""));
            }
        }

        theUI.NXMessageBox.Show("Debug - Parts", NXMessageBox.DialogType.Information, sb.ToString());
    }

    // Aplica os parâmetros padrão de non-cutting / cut pattern da operação.
    private void ConfigureDefaults(NXOpen.CAM.CavityMillingBuilder builder)
    {
        builder.NonCuttingBuilder.EngageClosedAreaBuilder.EngRetType = NXOpen.CAM.NcmPlanarEngRetBuilder.EngRetTypes.RampOnShape;
        builder.NonCuttingBuilder.EngageClosedAreaBuilder.HelicalRampAngleBuilder.Value = 1.0;
        builder.NonCuttingBuilder.TransferWithinLevelsType = NXOpen.CAM.NcmPlanarBuilder.TransferWithinLevelsTypes.PrevPlane;
        builder.NonCuttingBuilder.TransferWithinLevelsSafeDistanceBuilder.Value = 0.5;
        builder.NonCuttingBuilder.TransferBetweenRegionsBuilder.Type = NXOpen.CAM.NcmTransfer.TransferTypes.PrevPlane;
        builder.NonCuttingBuilder.TransferBetweenRegionsBuilder.SafeDistanceBuilder.Value = 0.0;
        builder.NonCuttingBuilder.ClearanceBuilder.ClearanceType = NXOpen.CAM.NcmClearanceBuilder.ClearanceTypes.Automatic;
        builder.NonCuttingBuilder.ClearanceBuilder.SafeDistance = 10.0;

        builder.CutPattern.CutPattern = NXOpen.CAM.CutPatternBuilder.Types.FollowPeriphery;
        builder.BndStepover.PercentToolFlatBuilder.Value = 50.0;
        builder.CutLevel.ApplyGlobalDepthPerCut();
        builder.CutParameters.IpwType = NXOpen.CAM.CutParametersIpwTypes.None;
        builder.CutParameters.TrimControl = NXOpen.CAM.CutParametersTrimControlTypes.Silhoutte;
        builder.CutParameters.PartStock.Value = 0.5;
        builder.CutParameters.CutOrder = NXOpen.CAM.CutParametersCutOrderTypes.DepthFirst;
    }

    // Aplica os valores vindos da UI (profundidade de corte, RPM, feed rate).
    private void ApplyUIValues(NXOpen.CAM.CavityMillingBuilder builder)
    {
        builder.CutLevel.GlobalDepthPerCut.DistanceBuilder.Value = integerCutDepth.Value;
        builder.FeedsBuilder.SpindleRpmBuilder.Value = integerRpm.Value;
        builder.FeedsBuilder.FeedCutBuilder.Value = integerFeedRate.Value;
    }

    // Cria a operação de Cavity Mill usando a ferramenta selecionada na lista,
    // as faces selecionadas, e os valores digitados nos campos da UI.
    private void RunCavityMill()
    {
        NXOpen.Part workPart = theSession.Parts.Work;

        NXOpen.CAM.Tool tool = GetSelectedTool(workPart);
        if (tool == null)
            return;

        NXOpen.Face[] faces = GetSelectedFaces();
        if (faces.Length == 0)
            return;

        NXOpen.CAM.NCGroup ncProgram = FindGroupByNameAndType<NXOpen.CAM.NCGroup>(workPart, NCGROUP_PROGRAM);
        NXOpen.CAM.Method method = FindGroupByNameAndType<NXOpen.CAM.Method>(workPart, NCGROUP_METHOD);
        NXOpen.CAM.FeatureGeometry workpiece = FindGroupByNameAndType<NXOpen.CAM.FeatureGeometry>(workPart, WORKPIECE_NAME);

        if (ncProgram == null || method == null || workpiece == null)
        {
            ShowError(
                "Não foi possível localizar um ou mais grupos CAM esperados.\n" +
                "Program: " + NCGROUP_PROGRAM + " -> " + (ncProgram == null ? "NÃO ENCONTRADO" : "OK") + "\n" +
                "Method:  " + NCGROUP_METHOD + " -> " + (method == null ? "NÃO ENCONTRADO" : "OK") + "\n" +
                "Workpiece: " + WORKPIECE_NAME + " -> " + (workpiece == null ? "NÃO ENCONTRADO" : "OK") + "\n" +
                "Confira os nomes reais no Operation Navigator (Program Order, Machine Method e Geometry View).");
            return;
        }

        string operationName = BuildOperationName(tool.Name);

        NXOpen.CAM.Operation operation = workPart.CAMSetup.CAMOperationCollection.CreateWithUserName(
            ncProgram, method, tool, workpiece,
            OPERATION_TEMPLATE, OPERATION_SUBTYPE,
            NXOpen.CAM.OperationCollection.UseDefaultName.False,
            operationName, operationName);

        NXOpen.CAM.CavityMillingBuilder builder =
            workPart.CAMSetup.CAMOperationCollection.CreateCavityMillingBuilder((NXOpen.CAM.CavityMilling)operation);

        ConfigureDefaults(builder);
        ApplyUIValues(builder);
        ApplyCutAreaGeometry(workPart, builder, faces);

        NXOpen.CAM.CavityMilling committed = (NXOpen.CAM.CavityMilling)builder.Commit();
        workPart.CAMSetup.GenerateToolPath(new NXOpen.CAM.CAMObject[] { committed });


        System.Windows.Forms.Application.DoEvents();

        builder.Destroy();

        UFSession theUFSession = UFSession.GetUFSession();
        theUFSession.Disp.Refresh();
    }
}